-- Dungeon Master's Guide v3.5 Chapter 7: standard magic rings, pp. 230-233.
-- Mechanical text is summarized; the supplied DMG and appended errata remain authoritative.
-- Rings use slot='other' to match the existing catalog convention; the equipment service may assign either ring slot at runtime.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dmg-3.5','dungeon-masters-guide-3-5','Dungeon Master''s Guide','DMG','Wizards of the Coast','dnd','3.5',
        'Core Rulebook II; source for D&D v3.5 magic items, treasure, special materials, and Dungeon Master rules.',NULL,1,0,NULL);

WITH desired(
 id,page,slug,name,description,rules_text,price_copper,caster_level,aura_strength,activation,activation_text,
 maximum_charges,recharge_text,craft_cost_copper,craft_xp_cost,crafting_text
) AS (VALUES
('dmg-ring-protection-1','231-232','ring-of-protection-1','Ring of Protection +1','A magic ring granting a continual deflection bonus to Armor Class.','Grants a +1 deflection bonus to AC.',200000,5,'faint','continuous','Deflection bonus applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; shield of faith; creator caster level at least three times the ring bonus.'),
('dmg-ring-feather-falling','232','ring-of-feather-falling','Ring of Feather Falling','A feather-patterned ring that arrests a dangerous fall.','Immediately activates as feather fall if the wearer falls more than 5 feet.',220000,1,'faint','continuous','Triggers immediately when the wearer falls more than 5 feet.',NULL,NULL,NULL,NULL,'Forge Ring; feather fall.'),
('dmg-ring-sustenance','233','ring-of-sustenance','Ring of Sustenance','A ring that nourishes and refreshes its wearer.','After one full week of continuous wear, provides life-sustaining nourishment and lets 2 hours of sleep provide the benefit of 8 hours. Removing the ring resets the one-week attunement.',250000,5,'faint','continuous','Requires one week of continuous wear to attune; removal resets attunement.',NULL,NULL,NULL,NULL,'Forge Ring; create food and water.'),
('dmg-ring-climbing','230','ring-of-climbing','Ring of Climbing','A magic leather finger cord that aids climbing.','Grants +5 competence on Climb checks.',250000,5,'faint','continuous','Competence bonus applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; creator must have 5 ranks in Climb.'),
('dmg-ring-jumping','232','ring-of-jumping','Ring of Jumping','A ring that magically enhances leaps.','Grants +5 competence on Jump checks.',250000,2,'faint','continuous','Competence bonus applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; creator must have 5 ranks in Jump.'),
('dmg-ring-swimming','233','ring-of-swimming','Ring of Swimming','A silver wave-patterned ring that aids swimming.','Grants +5 competence on Swim checks.',250000,2,'faint','continuous','Competence bonus applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; creator must have 5 ranks in Swim.'),
('dmg-ring-counterspells','230','ring-of-counterspells','Ring of Counterspells','A ring that stores one spell only to counter that same spell when it targets the wearer.','One spell of 1st through 6th level can be cast into the ring. If that spell is later cast upon the wearer, the ring automatically counters it with no action or knowledge required, then becomes empty until another spell is stored.',400000,11,'moderate','other','Store one spell in the ring; the matching incoming spell is countered automatically and consumes the stored spell.',1,'Stores one counterspell at a time; the stored spell is consumed when it counters a matching incoming spell.',NULL,NULL,'Forge Ring; imbue with spell ability.'),
('dmg-ring-mind-shielding','232','ring-of-mind-shielding','Ring of Mind Shielding','A finely made gold ring that wards the wearer's thoughts and alignment.','The wearer is continuously immune to detect thoughts, discern lies, and magical attempts to discern alignment.',800000,3,'faint','continuous','Mental and alignment shielding applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; nondetection.'),
('dmg-ring-protection-2','231-232','ring-of-protection-2','Ring of Protection +2','A magic ring granting a continual deflection bonus to Armor Class.','Grants a +2 deflection bonus to AC.',800000,5,'faint','continuous','Deflection bonus applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; shield of faith; creator caster level at least 6th.'),
('dmg-ring-force-shield','232','ring-of-force-shield','Ring of Force Shield','An iron ring that creates a weightless shield-shaped wall of force.','As a free action the wearer can activate or deactivate a force shield that functions as a heavy shield granting +2 shield AC, with no armor check penalty or arcane spell failure chance.',850000,9,'moderate','other','Activate or deactivate the force shield as a free action.',NULL,NULL,NULL,NULL,'Forge Ring; wall of force.'),
('dmg-ring-ram','232','ring-of-the-ram','Ring of the Ram','An ornate charged ring that projects a ramlike force.','Command the ring to spend 1-3 charges. The force has 50-foot maximum range and deals 1d6 damage per charge. Targets within 30 feet are also subject to a bull rush by a Large Strength 25 force, with +1 on the attempt for 2 charges or +2 for 3. Against doors, the effect uses Strength 25, 27, or 29 for 1, 2, or 3 charges. When all 50 charges are spent, the ring becomes nonmagical.',860000,9,'moderate','command_word','Command the ring and expend 1, 2, or 3 charges.',50,'Charges do not recharge; at 0 charges the ring becomes nonmagical.',NULL,NULL,'Forge Ring; bull''s strength; telekinesis.'),
('dmg-ring-climbing-improved','230','ring-of-climbing-improved','Ring of Climbing, Improved','A stronger ring of climbing.','Grants +10 competence on Climb checks.',1000000,5,'faint','continuous','Competence bonus applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; creator must have 10 ranks in Climb.'),
('dmg-ring-jumping-improved','232','ring-of-jumping-improved','Ring of Jumping, Improved','A stronger ring of jumping.','Grants +10 competence on Jump checks.',1000000,7,'moderate','continuous','Competence bonus applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; creator must have 10 ranks in Jump.'),
('dmg-ring-swimming-improved','233','ring-of-swimming-improved','Ring of Swimming, Improved','A stronger ring of swimming.','Grants +10 competence on Swim checks.',1000000,7,'moderate','continuous','Competence bonus applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; creator must have 10 ranks in Swim.'),
('dmg-ring-animal-friendship','230','ring-of-animal-friendship','Ring of Animal Friendship','A ring that charms animals on command.','On command, affects one animal as charm animal.',1080000,3,'faint','command_word','Command the ring to use charm animal.',NULL,NULL,NULL,NULL,'Forge Ring; charm animal.'),
('dmg-ring-energy-resistance-minor','231-232','ring-of-energy-resistance-minor','Ring of Energy Resistance, Minor','A ring attuned to one energy type chosen by its creator.','Continuously grants resistance 10 against one of acid, cold, electricity, fire, or sonic. The creator chooses the energy type; a treasure-generated ring determines the type randomly.',1200000,3,'faint','continuous','Energy resistance applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; resist energy.'),
('dmg-ring-chameleon-power','230','ring-of-chameleon-power','Ring of Chameleon Power','A ring that blends its wearer into the surroundings and can disguise them.','As a free action grants +10 competence on Hide checks. As a standard action the wearer can command disguise self at will.',1270000,3,'faint','other','Free action for chameleon blending; standard action to command disguise self.',NULL,NULL,NULL,NULL,'Forge Ring; disguise self; invisibility.'),
('dmg-ring-water-walking','233','ring-of-water-walking','Ring of Water Walking','An opal-set ring that keeps its wearer atop liquid surfaces.','Continuously provides the effects of water walk.',1500000,9,'moderate','continuous','Water-walk effect applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; water walk.'),
('dmg-ring-protection-3','231-232','ring-of-protection-3','Ring of Protection +3','A magic ring granting a continual deflection bonus to Armor Class.','Grants a +3 deflection bonus to AC.',1800000,5,'faint','continuous','Deflection bonus applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; shield of faith; creator caster level at least 9th.'),
('dmg-ring-spell-storing-minor','232-233','ring-of-spell-storing-minor','Ring of Spell Storing, Minor','A ring that stores spells for later use by any wearer.','Stores up to three total spell levels. Stored spells use the minimum caster level needed to cast them. The wearer can cast stored spells without material components, focuses, XP costs, or arcane spell failure; activation time is the stored spell casting time with a minimum of 1 standard action. Metamagic spells consume their adjusted spell level in storage.',1800000,5,'faint','other','Cast a stored spell using its casting time, minimum 1 standard action.',NULL,'Spell-level capacity is 3; expended spells can be replaced by a spellcaster or from a scroll.',NULL,NULL,'Forge Ring; imbue with spell ability.'),
('dmg-ring-invisibility','232','ring-of-invisibility','Ring of Invisibility','A simple silver ring that hides its wearer.','On activation, grants invisibility as the spell.',2000000,3,'faint','command_word','Activate to gain invisibility.',NULL,NULL,NULL,NULL,'Forge Ring; invisibility.'),
('dmg-ring-wizardry-1','233','ring-of-wizardry-1','Ring of Wizardry I','A ring for arcane spellcasters that doubles one level of daily spell slots.','Doubles the wearer''s 1st-level arcane spells per day. Bonus spells from high ability scores or school specialization are not doubled.',2000000,11,'moderate','continuous','Spell-slot multiplication applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; limited wish.'),
('dmg-ring-evasion','232','ring-of-evasion','Ring of Evasion','A ring that grants the wearer the defensive benefit of evasion.','Whenever the wearer makes a Reflex save for half damage, a successful save instead results in no damage.',2500000,7,'moderate','continuous','Evasion applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; jump.'),
('dmg-ring-x-ray-vision','233','ring-of-x-ray-vision','Ring of X-Ray Vision','A ring that lets its wearer see through solid matter on command.','On command, vision extends 20 feet through solid matter: up to 1 foot of stone, 1 inch of common metal, or 3 feet of wood or dirt; lead blocks the vision. After the first 10 minutes of use in one day, the wearer takes 1 Constitution damage for each additional minute of use.',2500000,6,'moderate','command_word','Command to use x-ray vision; extended daily use causes Constitution damage.',NULL,NULL,NULL,NULL,'Forge Ring; true seeing.'),
('dmg-ring-blinking','230','ring-of-blinking','Ring of Blinking','A ring that shifts its wearer rapidly between the Material and Ethereal Planes.','On command, the wearer gains blink as the spell.',2700000,7,'moderate','command_word','Command to gain blink.',NULL,NULL,NULL,NULL,'Forge Ring; blink.'),
('dmg-ring-energy-resistance-major','231-232','ring-of-energy-resistance-major','Ring of Energy Resistance, Major','A stronger energy-resistance ring attuned to one energy type.','Continuously grants resistance 20 against one of acid, cold, electricity, fire, or sonic. The creator chooses the energy type; a treasure-generated ring determines the type randomly.',2800000,7,'faint','continuous','Energy resistance applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; resist energy.'),
('dmg-ring-protection-4','231-232','ring-of-protection-4','Ring of Protection +4','A magic ring granting a continual deflection bonus to Armor Class.','Grants a +4 deflection bonus to AC.',3200000,5,'faint','continuous','Deflection bonus applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; shield of faith; creator caster level at least 12th.'),
('dmg-ring-wizardry-2','233','ring-of-wizardry-2','Ring of Wizardry II','A ring for arcane spellcasters that doubles one level of daily spell slots.','Doubles the wearer''s 2nd-level arcane spells per day. Bonus spells from high ability scores or school specialization are not doubled.',4000000,14,'strong','continuous','Spell-slot multiplication applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; limited wish.'),
('dmg-ring-freedom-movement','232','ring-of-freedom-of-movement','Ring of Freedom of Movement','A gold ring that prevents magical and mundane restraints on movement.','Continuously provides the effects of freedom of movement.',4000000,7,'moderate','continuous','Freedom-of-movement effect applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; freedom of movement.'),
('dmg-ring-energy-resistance-greater','231-232','ring-of-energy-resistance-greater','Ring of Energy Resistance, Greater','The strongest standard energy-resistance ring, attuned to one energy type.','Continuously grants resistance 30 against one of acid, cold, electricity, fire, or sonic. The creator chooses the energy type; a treasure-generated ring determines the type randomly.',4400000,11,'moderate','continuous','Energy resistance applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; resist energy.'),
('dmg-ring-friend-shield-pair','232','ring-of-friend-shield-pair','Rings of Friend Shield (Pair)','A matched pair of rings that let either wearer protect the other at any distance.','The pair functions only together. Either wearer can command their ring to cast shield other with the wearer of the mated ring as recipient, with no range limitation.',5000000,10,'moderate','command_word','Either wearer commands their ring to apply shield other to the wearer of the mate.',NULL,NULL,NULL,NULL,'Forge Ring; shield other.'),
('dmg-ring-protection-5','231-232','ring-of-protection-5','Ring of Protection +5','A magic ring granting a continual deflection bonus to Armor Class.','Grants a +5 deflection bonus to AC.',5000000,5,'faint','continuous','Deflection bonus applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; shield of faith; creator caster level at least 15th.'),
('dmg-ring-shooting-stars','232-233','ring-of-shooting-stars','Ring of Shooting Stars','A ring with different powers under open night skies and indoors or underground at night.','Outdoors at night or in shadow/darkness: dancing lights once per hour, light twice per night, ball lightning once per night, and three shooting stars per week. Ball lightning creates one to four controlled globes with total damage scaled by the number created. Shooting stars have 70-foot range, deal 12 impact damage plus a 5-foot-radius 24-fire-damage spread, Reflex DC 13 for the spread. Indoors at night or underground: faerie fire twice per day and a 20-foot-by-10-foot spark shower once per day dealing 2d8 damage, or 4d8 to creatures wearing metal armor and/or carrying metal weapons.',5000000,12,'strong','command_word','Command the environment-appropriate power; each power has its listed use frequency.',NULL,'Individual powers recharge on their own hourly, nightly, daily, or weekly schedules.',NULL,NULL,'Forge Ring; light; faerie fire; fireball; lightning bolt.'),
('dmg-ring-spell-storing','232-233','ring-of-spell-storing','Ring of Spell Storing','A ring that stores spells for later use by any wearer.','As the minor ring of spell storing, except it stores up to five total spell levels.',5000000,9,'moderate','other','Cast a stored spell using its casting time, minimum 1 standard action.',NULL,'Spell-level capacity is 5; expended spells can be replaced.',NULL,NULL,'Forge Ring; imbue with spell ability.'),
('dmg-ring-wizardry-3','233','ring-of-wizardry-3','Ring of Wizardry III','A ring for arcane spellcasters that doubles one level of daily spell slots.','Doubles the wearer''s 3rd-level arcane spells per day. Bonus spells from high ability scores or school specialization are not doubled.',7000000,17,'strong','continuous','Spell-slot multiplication applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; limited wish.'),
('dmg-ring-telekinesis','233','ring-of-telekinesis','Ring of Telekinesis','A ring that produces telekinesis on command.','Allows the wearer to use telekinesis on command.',7500000,9,'moderate','command_word','Command to use telekinesis.',NULL,NULL,NULL,NULL,'Forge Ring; telekinesis.'),
('dmg-ring-regeneration','232','ring-of-regeneration','Ring of Regeneration','A white-gold ring that accelerates natural recovery and regrows lost body parts.','For a living wearer, damage taken while wearing the ring heals at 1 hit point per level each hour rather than each day; nonlethal damage heals at 1 hit point per level every 5 minutes. Body parts lost while wearing it regenerate as the spell. Damage taken before putting on the ring is not regenerated by it.',9000000,15,'strong','continuous','Regenerative benefits apply while worn to damage or losses suffered while the ring is worn.',NULL,NULL,NULL,NULL,'Forge Ring; regenerate.'),
('dmg-ring-three-wishes','233','ring-of-three-wishes','Ring of Three Wishes','A ruby-set ring storing up to three wishes.','Each remaining ruby stores one wish. Using a wish makes its ruby disappear. A randomly generated ring has 1d3 remaining rubies. When all wishes are used, the ring becomes nonmagical.',9795000,20,'strong','other','Activate one remaining ruby to use wish.',3,'Wish charges do not recharge; at 0 charges the ring becomes nonmagical.',1147500,15918,'Forge Ring; wish or miracle.'),
('dmg-ring-spell-turning','233','ring-of-spell-turning','Ring of Spell Turning','A platinum ring that can reflect incoming spells.','Up to three times per day on command, the ring automatically reflects the next nine levels of spells cast at the wearer as spell turning.',9828000,13,'strong','command_word','Command up to three times per day; the effect reflects the next nine spell levels directed at the wearer.',NULL,'Three activations per day.',NULL,NULL,'Forge Ring; spell turning.'),
('dmg-ring-wizardry-4','233','ring-of-wizardry-4','Ring of Wizardry IV','A ring for arcane spellcasters that doubles one level of daily spell slots.','Doubles the wearer''s 4th-level arcane spells per day. Bonus spells from high ability scores or school specialization are not doubled.',10000000,20,'strong','continuous','Spell-slot multiplication applies while worn.',NULL,NULL,NULL,NULL,'Forge Ring; limited wish.'),
('dmg-ring-djinni-calling','230-231','ring-of-djinni-calling','Ring of Djinni Calling','A legendary ring bound to one specific djinni.','Rubbing the ring is a standard action. The bound djinni appears on the next round and faithfully serves the wearer for no more than 1 hour per day. If the bound djinni is killed, the ring becomes nonmagical and worthless.',12500000,17,'strong','other','Rub as a standard action; the djinni appears next round and serves for up to 1 hour that day.',NULL,'Bound djinni service is limited to 1 hour per day.',NULL,NULL,'Forge Ring; gate.'),
('dmg-ring-elemental-command-air','230-231','ring-of-elemental-command-air','Ring of Elemental Command (Air)','A powerful ring attuned to the Elemental Plane of Air that initially resembles a lesser ring until awakened.','Common elemental-command powers apply. Air powers: feather fall at will (wearer only), resist energy electricity at will (wearer only), gust of wind twice per day, wind wall at will, air walk once per day (wearer only), and chain lightning once per week. It initially appears as a ring of feather falling until a DM-established awakening condition is met, and must be awakened for each new wearer.',20000000,15,'strong','other','Common elemental-command protections are continuous; individual air powers use their listed activation frequencies after the ring is awakened.',NULL,'Individual powers recharge on their listed daily or weekly schedules; at-will powers are unlimited.',NULL,NULL,'Forge Ring; summon monster VI; all appropriate spells.'),
('dmg-ring-elemental-command-earth','230-231','ring-of-elemental-command-earth','Ring of Elemental Command (Earth)','A powerful ring attuned to the Elemental Plane of Earth that initially resembles a lesser ring until awakened.','Common elemental-command powers apply. Earth powers: meld into stone at will (wearer only), soften earth or stone at will, stone shape twice per day, stoneskin once per week (wearer only), passwall twice per week, and wall of stone once per day. It initially appears as a ring of meld into stone until the DM-established awakening condition is met.',20000000,15,'strong','other','Common elemental-command protections are continuous; individual earth powers use their listed frequencies after awakening.',NULL,'Individual powers recharge on their listed daily or weekly schedules; at-will powers are unlimited.',NULL,NULL,'Forge Ring; summon monster VI; all appropriate spells.'),
('dmg-ring-elemental-command-fire','230-231','ring-of-elemental-command-fire','Ring of Elemental Command (Fire)','A powerful ring attuned to the Elemental Plane of Fire that initially resembles a lesser ring until awakened.','Common elemental-command powers apply. Fire powers: fire resistance as a major ring of energy resistance, burning hands at will, flaming sphere twice per day, pyrotechnics twice per day, wall of fire once per day, and flame strike twice per week. It initially appears as a major ring of fire resistance until the DM-established awakening condition is met.',20000000,15,'strong','other','Common elemental-command protections are continuous; individual fire powers use their listed frequencies after awakening.',NULL,'Individual powers recharge on their listed daily or weekly schedules; at-will powers are unlimited.',NULL,NULL,'Forge Ring; summon monster VI; all appropriate spells.'),
('dmg-ring-elemental-command-water','230-231','ring-of-elemental-command-water','Ring of Elemental Command (Water)','A powerful ring attuned to the Elemental Plane of Water that initially resembles a lesser ring until awakened.','Common elemental-command powers apply. Water powers: water walk at will, create water at will, water breathing at will, wall of ice once per day, ice storm twice per week, and control water twice per week. It initially appears as a ring of water walking until the DM-established awakening condition is met.',20000000,15,'strong','other','Common elemental-command protections are continuous; individual water powers use their listed frequencies after awakening.',NULL,'Individual powers recharge on their listed daily or weekly schedules; at-will powers are unlimited.',NULL,NULL,'Forge Ring; summon monster VI; all appropriate spells.'),
('dmg-ring-spell-storing-major','232-233','ring-of-spell-storing-major','Ring of Spell Storing, Major','The strongest standard ring of spell storing.','As the minor ring of spell storing, except it stores up to ten total spell levels.',20000000,17,'strong','other','Cast a stored spell using its casting time, minimum 1 standard action.',NULL,'Spell-level capacity is 10; expended spells can be replaced.',NULL,NULL,'Forge Ring; imbue with spell ability.')
)
INSERT INTO dnd35_items
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,price_copper,weight_pounds,size,hardness,hit_points)
SELECT d.id,'dmg-3.5',d.page,d.slug,d.name,d.description,d.rules_text,0,NULL,1,
       'magic',d.price_copper,NULL,NULL,NULL,NULL
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_items i WHERE i.source_id='dmg-3.5' AND i.slug=d.slug AND i.owner_user_id IS NULL
);

