INSERT OR IGNORE INTO dnd35_magic_items
  (item_id,aura_school_id,caster_level,manifester_level,aura_strength,activation,activation_text,slot,
   maximum_charges,recharge_text,enhancement_bonus,craft_cost_copper,craft_xp_cost,crafting_text,crafting_prerequisites)
SELECT d.item_id,NULL,d.caster_level,NULL,d.aura_strength,d.activation,d.activation_text,'other',
       d.maximum_charges,d.recharge_text,0,d.craft_cost_copper,d.craft_xp_cost,d.crafting_text,NULL
FROM desired d;

-- Shared ring behavior and random-generation support.
WITH desired(slug,name,page,kind,summary,tags,mechanics) AS (VALUES
('dmg-ring-energy-type-table','Ring of Energy Resistance Type Table','232','table',
 'When a ring of energy resistance is found in a treasure hoard, determine the protected energy type randomly.',
 '["magic-items","rings","energy-resistance","random-generation"]',
 '{"energyTypes":["acid","cold","electricity","fire","sonic"],"selection":"random"}'),
('dmg-ring-elemental-command-common','Ring of Elemental Command Common Powers','230-231','rule',
 'All four elemental-command rings share protection, offense, communication, and planar drawbacks tied to their attuned plane.',
 '["magic-items","rings","elemental-command"]',
 '{"elementalsCannotAttackOrApproachWithinFeet":5,"mayForegoProtectionToAttemptCharmMonster":{"willDc":17,"failedCharmPermanentlyEndsAbsoluteProtection":true},"attunedPlanarCreaturesAttackPenalty":-1,"wearerResistanceSaveBonusAgainstAttunedPlanarCreatures":2,"wearerMoraleAttackBonusAgainstAttunedPlanarCreatures":4,"weaponsBypassAttunedCreatureDamageReduction":true,"canCommunicateWithAttunedPlanarCreatures":true,"savingThrowPenalty":{"air":"-2 vs earth-based effects","earth":"-2 vs air- or electricity-based effects","fire":"-2 vs water- or cold-based effects","water":"-2 vs fire-based effects"}}'),
('dmg-ring-special-qualities','Random Ring Special Qualities','229','table',
 'Randomly generated rings can be intelligent or carry a clue to function. Charged rings can never be intelligent.',
 '["magic-items","rings","intelligent-items","random-generation"]',
 '{"ranges":[[1,1,"intelligent"],[2,31,"function-clue"],[32,100,"none"]],"chargedRingsCannotBeIntelligent":true}'),
('dmg-ring-spell-storing-random-fill','Random Spell-Storing Ring Contents','232-233','procedure',
 'To fill a randomly generated spell-storing ring, generate stored spells as scroll spells until another result would exceed the ring capacity; not every discovered ring must be completely filled.',
 '["magic-items","rings","spell-storing","random-generation"]',
