mental-command-earth"],[98,98,"ring-of-elemental-command-fire"],[99,99,"ring-of-elemental-command-water"],[100,100,"ring-of-spell-storing-major"]],"sourceExtractionAmbiguity":{"medium":[{"printedTextExtraction":"47-51 Animal friendship"},{"printedTextExtraction":"50-56 Energy resistance, minor"}],"status":"unresolved-from-text-layer"}}')
